import RAPIER from '@dimforge/rapier3d-compat';
import * as THREE from 'three';
import { planShot, powerToSpeed } from '../ai/BotPlanner';
import { BotTurnScheduler } from '../ai/BotTurnScheduler';
import { selectBotOpponents } from '../ai/Matchmaking';
import type { BotPlan, BotProfile } from '../ai/types';
import { CameraController } from '../camera/CameraController';
import { GAME_CONFIG } from '../config/GameConfig';
import type {
  ControlScheme,
  MatchDTO,
  PlayerHoleScore,
  PlayerProfile,
  ShotCommand,
} from '../contracts/game';
import type { Vec3 } from '../contracts/math';
import { HoleSceneBuilder } from '../core/HoleSceneBuilder';
import { SceneManager } from '../core/SceneManager';
import type { Course, Hole } from '../courses/types';
import { HoleSystem } from '../gameplay/HoleSystem';
import { MatchManager } from '../gameplay/MatchManager';
import { calculateMatchReward } from '../gameplay/MatchRewards';
import { computeMatchRatings, participantsFromStandings } from '../gameplay/RatingSystem';
import { ScoreManager } from '../gameplay/ScoreManager';
import type { InputSnapshot, PointerSnapshot } from '../input/InputManager';
import type { InputManager } from '../input/InputManager';
import { GolfBallPhysics } from '../physics/GolfBallPhysics';
import { PhysicsWorld } from '../physics/PhysicsWorld';
import { clamp } from '../physics/helpers';
import { DEFAULT_BALL_ID, ballStyleById } from '../player/cosmetics';
import { Hud, MatchResults, PauseOverlay, Scoreboard } from '../ui';
import { Minimap, buildMinimapModel } from '../ui/Minimap';
import { element } from '../ui/dom';
import type { MatchResultPlayer, UiPlayer, UiPlayerStatus } from '../ui/types';
import { AimController } from './AimController';
import { limitCourse, resolveCourse } from './CourseRegistry';
import { HoleRuntime } from './HoleRuntime';
import './game.css';

export interface GameOptions {
  renderer: THREE.WebGLRenderer;
  camera: THREE.PerspectiveCamera;
  input: InputManager;
  overlayRoot: HTMLElement;
  courseId: string;
  holeCount: number;
  humanCount: number;
  botCount: number;
  controlScheme: ControlScheme;
  startHoleIndex?: number;
  playerName?: string;
  playerRating?: number;
  ballStyleId?: string;
  onExit?: () => void;
}

/** Mass chosen so the configured impulse range maps onto arcade shot speeds. */
const BALL_MASS = 0.75;
const BALL_FRICTION = 0.5;
const BALL_RESTITUTION = 0.45;
const INTRO_SECONDS = 1.3;
const HOLE_SUMMARY_SECONDS = 2.8;
const SETTLE_SECONDS = 0.3;
const SHOT_TIMEOUT_SECONDS = 22;
const TOAST_SECONDS = 2.2;
const AIRBORNE_SPEED = 2.5;
const MINIMAP_INTERVAL = 0.12;
const STROKE_LIMIT = 8;
const CAMERA_PITCH = 0.38;
const CAMERA_DISTANCE = 6.5;
const PLAYER_COLORS = ['#8cf2c2', '#ffbd59', '#5ab8ff', '#ff7b7b', '#c084fc', '#f9a8d4', '#7ef0d2', '#ffd166'];

/** Maps an arcade 0..1 power onto the charge the configured impulse curve expects. */
function chargeForPower(power: number): number {
  const config = GAME_CONFIG.physics;
  const impulse = powerToSpeed(clamp(power, 0, 1)) * BALL_MASS;
  const span = config.maxShotPower - config.minShotPower;
  if (span <= 0 || impulse <= config.minShotPower) return 0;
  return Math.min(1, Math.pow((impulse - config.minShotPower) / span, 1 / config.powerExponent));
}

/**
 * Playable match loop: builds hole scenes and colliders, drives aiming, shots and bot
 * turns through MatchManager, and renders HUD, scoreboard and results on top of WebGL.
 */
export class Game {
  static async create(options: GameOptions): Promise<Game> {
    await RAPIER.init();
    return new Game(options);
  }

  private readonly sceneManager = new SceneManager();
  private readonly builder = new HoleSceneBuilder();
  private readonly physics = new PhysicsWorld();
  private readonly matchManager = new MatchManager();
  private readonly holeSystem = new HoleSystem();
  private readonly scoreManager = new ScoreManager();
  private readonly botScheduler = new BotTurnScheduler();
  private readonly cameraController = new CameraController({ pitch: CAMERA_PITCH, distance: CAMERA_DISTANCE });
  private readonly hud = new Hud();
  private readonly scoreboard = new Scoreboard();
  private readonly results = new MatchResults();
  private readonly minimap = new Minimap();
  private readonly hint = element('div', 'cpa-hint');
  private readonly toastElement = element('div', 'cpa-toast');
  private readonly exitButton = element('button', 'ui-button', 'BACK TO MENU');
  private readonly botProfiles = new Map<string, BotProfile>();
  private readonly playerPositions = new Map<string, Vec3>();
  private readonly ballMeshes = new Map<string, THREE.Mesh>();
  private readonly ballGeometry = new THREE.SphereGeometry(GAME_CONFIG.physics.ballRadius, 24, 16);
  private readonly ballMaterials: THREE.MeshStandardMaterial[] = [];
  private readonly aimMaterial = new THREE.MeshBasicMaterial({ color: 0x8cf2c2, transparent: true, opacity: 0.92 });
  private readonly aimArrow: THREE.Group;
  private readonly aim: AimController;
  private readonly pauseOverlay: PauseOverlay;
  private readonly course: Course;
  private match: MatchDTO;
  private hole!: Hole;
  private holeIndex = -1;
  private runtime?: HoleRuntime;
  private ball?: GolfBallPhysics;
  private botPlan?: BotPlan;
  private turnPlayerId?: string;
  private sequence = 0;
  private introClock = 0;
  private shotClock = 0;
  private settleClock = 0;
  private toastClock = 0;
  private minimapClock = 0;
  private aimPower = 0;
  private statusText?: string;
  private paused = false;
  private disposed = false;

  private constructor(private readonly options: GameOptions) {
    this.aim = new AimController(options.controlScheme);
    this.pauseOverlay = new PauseOverlay(() => this.togglePause(), undefined, () => this.exit());
    this.course = limitCourse(resolveCourse(options.courseId), options.holeCount);
    this.match = this.createMatch();
    this.aimArrow = this.createAimArrow();
    this.sceneManager.addTransient(this.aimArrow);
    this.createBallMeshes();
    this.mountUi();
    this.loadHole(this.match.currentHoleIndex);
  }

  get scene(): THREE.Scene {
    return this.sceneManager.scene;
  }

  get courseName(): string {
    return this.course.name;
  }

  setControlScheme(scheme: ControlScheme): void {
    this.aim.setScheme(scheme);
    this.hint.textContent = this.hintText();
  }

  /** One rendered frame: input, fixed step physics, turn logic, presentation. */
  frame(dt: number): void {
    if (this.disposed) return;
    const step = clamp(dt, 0, 0.05);
    if (this.options.input.wasPressed('pause')) this.togglePause();
    if (!this.paused) {
      this.physics.step(step, (fixed) => {
        this.runtime?.update(fixed);
        this.applyRollingResistance(fixed);
        this.ball?.update(fixed);
      });
      this.advance(step);
    }
    this.updateCamera(step);
    this.syncMeshes();
    this.updatePresentation(step);
  }

  dispose(): void {
    if (this.disposed) return;
    this.disposed = true;
    this.runtime?.dispose();
    this.runtime = undefined;
    this.disposeBall();
    for (const mesh of this.ballMeshes.values()) mesh.removeFromParent();
    this.ballMeshes.clear();
    this.ballGeometry.dispose();
    for (const material of this.ballMaterials) material.dispose();
    this.aimMaterial.dispose();
    for (const node of [
      this.hud.element,
      this.scoreboard.element,
      this.results.element,
      this.pauseOverlay.element,
      this.minimap.element,
      this.hint,
      this.toastElement,
    ]) {
      node.remove();
    }
    this.sceneManager.dispose();
    this.builder.dispose();
    this.physics.dispose();
  }

  private createMatch(): MatchDTO {
    const rating = this.options.playerRating ?? 1000;
    const humans = Math.max(1, Math.min(GAME_CONFIG.maxPlayers, Math.floor(this.options.humanCount)));
    const bots = Math.max(0, Math.min(GAME_CONFIG.maxPlayers - humans, Math.floor(this.options.botCount)));
    const players: PlayerProfile[] = [];
    for (let index = 0; index < humans; index += 1) {
      players.push({
        id: index === 0 ? 'local-player' : 'local-player-' + String(index + 1),
        displayName: index === 0 ? this.options.playerName ?? 'You' : 'Player ' + String(index + 1),
        kind: 'human',
        ballStyleId: this.options.ballStyleId ?? DEFAULT_BALL_ID,
        rating,
      });
    }
    for (const profile of selectBotOpponents(rating, bots, { seed: this.course.id + ':' + String(bots) })) {
      this.botProfiles.set(profile.id, profile);
      players.push({
        id: profile.id,
        displayName: profile.displayName,
        kind: 'bot',
        ballStyleId: DEFAULT_BALL_ID,
        rating: profile.rating,
      });
    }

    const settings = {
      courseId: this.course.id,
      maxPlayers: GAME_CONFIG.maxPlayers,
      strokeLimitPerHole: STROKE_LIMIT,
    };
    let match = this.matchManager.createMatch('match-' + String(Date.now()), settings, players);
    match = this.matchManager.startMatch(match, this.course);

    const startIndex = Math.round(
      clamp(Math.floor(this.options.startHoleIndex ?? 0), 0, this.course.holes.length - 1),
    );
    const startHole = this.course.holes[startIndex];
    if (startIndex > 0 && startHole) {
      match = {
        ...match,
        currentHoleIndex: startIndex,
        players: match.players.map((player) => ({
          ...player,
          holeScores: [...player.holeScores, this.scoreManager.createHoleScore(player.id, startHole.id)],
        })),
      };
    }
    return match;
  }

  private mountUi(): void {
    this.scoreboard.element.hidden = true;
    this.results.element.hidden = true;
    this.pauseOverlay.element.hidden = true;
    this.toastElement.hidden = true;
    this.hint.textContent = this.hintText();
    this.exitButton.addEventListener('click', () => this.exit());
    this.minimap.setVisible(true);
    this.options.overlayRoot.append(
      this.hud.element,
      this.minimap.element,
      this.hint,
      this.toastElement,
      this.scoreboard.element,
      this.pauseOverlay.element,
      this.results.element,
    );
  }

  private createAimArrow(): THREE.Group {
    const group = new THREE.Group();
    group.name = 'aim-arrow';
    group.visible = false;
    const shaft = new THREE.Mesh(new THREE.BoxGeometry(0.09, 0.02, 1), this.aimMaterial);
    shaft.position.z = 0.5;
    const head = new THREE.Mesh(new THREE.ConeGeometry(0.13, 0.3, 12), this.aimMaterial);
    head.rotation.x = Math.PI / 2;
    head.position.z = 1.05;
    group.add(shaft, head);
    return group;
  }

  private createBallMeshes(): void {
    this.match.players.forEach((player, index) => {
      const material = new THREE.MeshStandardMaterial({
        color: new THREE.Color(this.colorOf(player.id, index)),
        roughness: 0.35,
        metalness: 0.05,
      });
      this.ballMaterials.push(material);
      const mesh = new THREE.Mesh(this.ballGeometry, material);
      mesh.name = 'ball-' + player.id;
      mesh.castShadow = true;
      this.ballMeshes.set(player.id, mesh);
      this.sceneManager.addDynamic(mesh);
    });
  }

  private loadHole(index: number): void {
    const hole = this.course.holes[index];
    if (!hole) return;
    const first = this.holeIndex < 0;
    this.holeIndex = index;
    this.hole = hole;
    this.runtime?.dispose();
    this.disposeBall();
    this.runtime = new HoleRuntime(this.physics, hole, this.builder);
    this.sceneManager.addStatic(this.runtime.group);
    this.ball = new GolfBallPhysics(this.physics, hole.spawn, {
      mass: BALL_MASS,
      friction: BALL_FRICTION,
      restitution: BALL_RESTITUTION,
      rollingResistance: 0,
      airResistance: 0,
    });
    this.playerPositions.clear();
    for (const player of this.match.players) {
      this.playerPositions.set(player.id, { ...hole.spawn });
      this.holeSystem.setInitialSafePosition(player.id, hole.spawn);
    }
    this.turnPlayerId = undefined;
    this.botPlan = undefined;
    this.botScheduler.reset();
    this.aim.cancel();
    this.aimPower = 0;
    this.statusText = undefined;
    this.introClock = first ? 0 : -HOLE_SUMMARY_SECONDS;
    this.sceneManager.setSunTarget(
      new THREE.Vector3(hole.cup.position.x, hole.cup.position.y, hole.cup.position.z),
    );
    this.focusCamera(hole.spawn);
    this.toast('HOLE ' + String(index + 1) + ' · ' + hole.name.toUpperCase() + ' · PAR ' + String(hole.par));
  }

  private advance(dt: number): void {
    if (this.match.currentHoleIndex !== this.holeIndex && this.match.phase !== 'match-results') {
      this.loadHole(this.match.currentHoleIndex);
      return;
    }
    if (this.match.phase === 'hole-intro') {
      this.introClock += dt;
      if (this.introClock >= INTRO_SECONDS) {
        this.match = this.matchManager.beginAiming(this.match, this.hole);
        this.syncTurn();
      }
      return;
    }
    if (this.match.phase === 'aiming') {
      this.updateAiming(dt);
      return;
    }
    if (this.match.phase === 'simulating') this.updateSimulation(dt);
  }

  private updateAiming(dt: number): void {
    const playerId = this.match.activePlayerId;
    if (!playerId || !this.ball) return;
    if (playerId !== this.turnPlayerId) this.syncTurn();

    const bot = this.botProfiles.get(playerId);
    if (bot) {
      const status = this.botScheduler.update(dt);
      this.statusText = status.statusText === '' ? undefined : status.statusText;
      const plan = this.botPlan;
      if (plan && status.showAimLine) {
        this.aimPower = plan.command.normalizedPower * status.progress;
        this.showAim(plan.command.direction, this.aimPower);
      } else if (!status.fireShot) {
        this.aimPower = 0;
        this.aimArrow.visible = false;
      }
      if (status.fireShot && plan) {
        this.botPlan = undefined;
        this.fireShot(playerId, plan.command.direction, plan.command.normalizedPower);
      }
      return;
    }

    const sample = this.aim.update(dt, this.inputView(), this.cameraController.state.yaw, true);
    this.aimPower = sample.power;
    this.showAim(sample.direction, sample.power);
    if (sample.fired) {
      this.aim.cancel();
      this.fireShot(playerId, sample.direction, sample.power);
    }
  }

  private updateSimulation(dt: number): void {
    const playerId = this.turnPlayerId;
    if (!playerId || !this.ball) return;
    this.shotClock += dt;
    const position = this.ball.position;
    const speed = this.ball.speed;

    if (this.holeSystem.isBallHoled(this.hole, position, speed)) {
      this.completeHole(playerId);
      return;
    }
    const hazard = this.runtime?.hazardAt(position);
    if (hazard || this.holeSystem.isOutsideBounds(this.hole, position)) {
      this.resetBall(playerId, hazard);
      return;
    }
    if (this.ball.canShoot) {
      this.settleClock += dt;
      if (this.settleClock >= SETTLE_SECONDS) this.finishTurn(playerId, position);
      return;
    }
    this.settleClock = 0;
    if (this.shotClock > SHOT_TIMEOUT_SECONDS) {
      const safe = this.holeSystem.getLastSafePosition(playerId, this.hole.spawn);
      this.ball.reset(safe);
      this.finishTurn(playerId, safe);
    }
  }

  private fireShot(playerId: string, direction: Vec3, normalizedPower: number): void {
    if (!this.ball) return;
    const power = clamp(normalizedPower, 0.01, 1);
    const result = this.ball.applyShot(direction, chargeForPower(power));
    if (!result.accepted) return;
    this.sequence += 1;
    const command: ShotCommand = {
      playerId,
      holeId: this.hole.id,
      direction: { x: direction.x, y: 0, z: direction.z },
      normalizedPower: power,
      clientSequence: this.sequence,
      issuedAt: Date.now(),
    };
    this.match = this.matchManager.markShotSubmitted(this.match);
    this.match = this.matchManager.applySimulationEvent(this.match, this.course, {
      type: 'shot-accepted',
      command,
    });
    this.shotClock = 0;
    this.settleClock = 0;
    this.aimPower = 0;
    this.statusText = undefined;
    this.aimArrow.visible = false;
  }

  private finishTurn(playerId: string, position: Vec3): void {
    this.playerPositions.set(playerId, { ...position });
    this.holeSystem.markSafePosition(playerId, position);
    const score = this.scoreOf(playerId);
    if (score && !score.completed && score.strokes >= this.match.settings.strokeLimitPerHole) {
      this.match = this.matchManager.enforceStrokeLimit(this.match, this.course, playerId);
      this.toast('STROKE LIMIT · ' + this.nameOf(playerId).toUpperCase());
    } else {
      this.match = this.matchManager.applySimulationEvent(this.match, this.course, {
        type: 'ball-stopped',
        playerId,
        position: { ...position },
      });
    }
    this.afterMatchUpdate();
  }

  private completeHole(playerId: string): void {
    const strokes = this.scoreOf(playerId)?.strokes ?? 0;
    this.playerPositions.set(playerId, { ...this.hole.cup.position });
    this.match = this.matchManager.applySimulationEvent(this.match, this.course, {
      type: 'ball-holed',
      playerId,
      holeId: this.hole.id,
      strokes,
    });
    this.toast(this.nameOf(playerId).toUpperCase() + ' · ' + this.scoreManager.parLabel(strokes, this.hole.par));
    this.afterMatchUpdate();
  }

  private resetBall(playerId: string, hazard: ReturnType<HoleRuntime['hazardAt']>): void {
    if (!this.ball) return;
    const resolution = this.holeSystem.resolveHazard(playerId, this.hole, hazard);
    this.ball.reset(resolution.resetPosition);
    this.match = this.matchManager.applySimulationEvent(this.match, this.course, {
      type: 'ball-reset',
      playerId,
      position: resolution.resetPosition,
      penaltyStrokes: resolution.penaltyStrokes,
    });
    this.toast((hazard ? 'HAZARD' : 'OUT OF BOUNDS') + ' · +' + String(resolution.penaltyStrokes));
    this.finishTurn(playerId, resolution.resetPosition);
  }

  private afterMatchUpdate(): void {
    if (this.match.phase === 'match-results') {
      this.showResults();
      return;
    }
    if (this.match.currentHoleIndex !== this.holeIndex) {
      this.loadHole(this.match.currentHoleIndex);
      return;
    }
    this.syncTurn();
  }

  private syncTurn(): void {
    const playerId = this.match.activePlayerId;
    if (!playerId || this.match.phase !== 'aiming') return;
    this.turnPlayerId = playerId;
    const position = this.playerPositions.get(playerId) ?? this.hole.spawn;
    this.ball?.reset(position);
    this.holeSystem.markSafePosition(playerId, position);
    this.aim.cancel();
    this.aimPower = 0;
    this.shotClock = 0;
    this.settleClock = 0;
    this.focusCamera(position);

    const bot = this.botProfiles.get(playerId);
    if (!bot) {
      this.botScheduler.reset();
      this.botPlan = undefined;
      this.statusText = undefined;
      return;
    }
    this.botScheduler.begin(bot.displayName, bot.personality);
    this.botPlan = planShot(bot, {
      playerId,
      hole: this.hole,
      ballPosition: position,
      clientSequence: this.sequence + 1,
      issuedAt: Date.now(),
      seed: playerId + ':' + this.hole.id + ':' + String(this.sequence),
    });
  }

  /** Arcade rolling model: constant deceleration while the ball hugs the surface. */
  private applyRollingResistance(dt: number): void {
    const ball = this.ball;
    if (!ball) return;
    const velocity = ball.velocity;
    if (Math.abs(velocity.y) > AIRBORNE_SPEED) return;
    const horizontal = Math.hypot(velocity.x, velocity.z);
    if (horizontal <= 1e-4) return;
    const deceleration = this.runtime?.decelerationAt(ball.position) ?? 3.4;
    const factor = Math.max(0, horizontal - deceleration * dt) / horizontal;
    ball.body.setLinvel({ x: velocity.x * factor, y: velocity.y, z: velocity.z * factor }, true);
  }

  private updateCamera(dt: number): void {
    if (this.match.phase === 'simulating' || this.match.phase === 'hole-intro') {
      const focus = this.ballPosition();
      this.cameraController.setTarget({ x: focus.x, y: focus.y + 0.35, z: focus.z });
    }
    const state = this.cameraController.update(dt, this.cameraView());
    if (this.options.input.wasPressed('camera-reset')) {
      this.focusCamera(this.ballPosition());
    }
    const pose = this.cameraController.state;
    const camera = this.options.camera;
    camera.position.set(pose.position.x, pose.position.y, pose.position.z);
    camera.lookAt(state.target.x, state.target.y, state.target.z);
  }

  private focusCamera(position: Vec3): void {
    const dx = this.hole.cup.position.x - position.x;
    const dz = this.hole.cup.position.z - position.z;
    const yaw = Math.abs(dx) + Math.abs(dz) < 1e-5 ? Math.PI : Math.atan2(-dx, -dz);
    this.cameraController.reset({ x: position.x, y: position.y + 0.35, z: position.z });
    this.cameraController.setOrbit(yaw, CAMERA_PITCH, CAMERA_DISTANCE);
  }

  private syncMeshes(): void {
    for (const [playerId, mesh] of this.ballMeshes) {
      const completed = this.scoreOf(playerId)?.completed === true;
      const live = playerId === this.turnPlayerId && this.ball;
      const position = live ? this.ball.position : this.playerPositions.get(playerId);
      if (position) mesh.position.set(position.x, position.y, position.z);
      if (live && this.ball) {
        const rotation = this.ball.body.rotation();
        mesh.quaternion.set(rotation.x, rotation.y, rotation.z, rotation.w);
      }
      mesh.visible = !completed;
    }
  }

  private updatePresentation(dt: number): void {
    const input = this.options.input;
    this.minimapClock += dt;
    if (this.minimapClock >= MINIMAP_INTERVAL) {
      this.minimapClock = 0;
      this.minimap.render(buildMinimapModel(this.hole, this.ballPosition()));
    }
    if (this.toastClock > 0) {
      this.toastClock -= dt;
      if (this.toastClock <= 0) this.toastElement.hidden = true;
    }

    const humanTurn = this.isHumanTurn();
    this.hud.render({
      holeNumber: this.holeIndex + 1,
      holeCount: this.course.holes.length,
      holeName: this.hole.name,
      par: this.hole.par,
      strokes: this.scoreOf(this.turnPlayerId ?? '')?.strokes ?? 0,
      power: this.aimPower,
      canShoot: humanTurn && this.match.phase === 'aiming' && (this.ball?.canShoot ?? false),
      statusText: this.statusLine(),
    });
    this.hint.hidden = this.match.phase === 'match-results' || this.paused;

    const scoreboardVisible =
      !this.results.element.hidden === false &&
      (input.isDown('scoreboard') || this.introClock < 0 || this.paused);
    this.scoreboard.element.hidden = !scoreboardVisible;
    if (scoreboardVisible) {
      this.scoreboard.render({
        players: this.uiPlayers(),
        holeNumber: this.holeIndex + 1,
        holeCount: this.course.holes.length,
      });
    }
  }

  private showAim(direction: Vec3, power: number): void {
    const ball = this.ball;
    if (!ball) return;
    const position = ball.position;
    this.aimArrow.visible = true;
    this.aimArrow.position.set(position.x, position.y + 0.02, position.z);
    this.aimArrow.rotation.set(0, Math.atan2(direction.x, direction.z), 0);
    const length = 0.85 + clamp(power, 0, 1) * 3.4;
    this.aimArrow.scale.set(1, 1, length);
    this.aimMaterial.color.setHex(power > 0.86 ? 0xffbd59 : 0x8cf2c2);
  }

  private showResults(): void {
    const standings = this.scoreManager.standings(this.match.players);
    const profiles: PlayerProfile[] = this.match.players.map((player) => ({
      id: player.id,
      displayName: player.displayName,
      kind: player.kind,
      ballStyleId: player.ballStyleId,
      rating: player.rating,
    }));
    const changes = computeMatchRatings(participantsFromStandings(standings, profiles));
    const rows = this.uiPlayers();
    const coursePar = this.course.holes.reduce((sum, hole) => sum + hole.par, 0);
    const finishedAt = this.match.finishedAt ?? Date.now();
    const durationSeconds = Math.max(0, Math.round((finishedAt - (this.match.startedAt ?? finishedAt)) / 1000));
    const players: MatchResultPlayer[] = [];

    for (const standing of standings) {
      const row = rows.find((entry) => entry.id === standing.playerId);
      if (!row) continue;
      const player = this.match.players.find((entry) => entry.id === standing.playerId);
      const holeScores = player?.holeScores ?? [];
      const change = changes.find((entry) => entry.playerId === standing.playerId);
      const reward = calculateMatchReward({
        rank: standing.rank,
        playerCount: this.match.players.length,
        holesPlayed: this.course.holes.length,
        holesCompleted: holeScores.filter((score) => score.completed).length,
        totalStrokes: standing.totalStrokes,
        coursePar,
        holesInOne: holeScores.filter((score) => score.completed && score.strokes === 1).length,
        birdies: holeScores.filter((score) => score.completed && score.strokes === this.parOf(score.holeId) - 1).length,
        durationSeconds,
      });
      players.push({
        ...row,
        rank: standing.rank,
        ratingBefore: change?.ratingBefore,
        ratingAfter: change?.ratingAfter,
        xpEarned: reward.xp,
      });
    }

    this.results.render({
      players,
      courseName: this.course.name,
      holesPlayed: this.course.holes.length,
    });
    this.results.element.append(this.exitButton);
    this.results.element.hidden = false;
    this.scoreboard.element.hidden = true;
    this.aimArrow.visible = false;
    this.statusText = undefined;
  }

  private togglePause(): void {
    if (this.match.phase === 'paused') {
      this.match = this.matchManager.resume(this.match);
      this.paused = false;
    } else if (this.match.phase === 'aiming' || this.match.phase === 'simulating') {
      this.match = this.matchManager.pause(this.match);
      this.paused = true;
      this.aim.cancel();
      this.aimPower = 0;
    } else {
      return;
    }
    this.pauseOverlay.element.hidden = !this.paused;
  }

  private exit(): void {
    this.options.onExit?.();
  }

  private inputView(): InputSnapshot {
    return this.options.input;
  }

  /** Camera orbit ignores pointer motion while a shot is being charged. */
  private cameraView(): InputSnapshot {
    const input = this.options.input;
    if (!this.aim.isCharging && !this.paused) return input;
    const pointer: PointerSnapshot = { ...input.pointer, deltaX: 0, deltaY: 0, wheel: 0 };
    return {
      pointer,
      isDown: (action) => input.isDown(action),
      wasPressed: (action) => input.wasPressed(action),
      wasReleased: (action) => input.wasReleased(action),
    };
  }

  private uiPlayers(): UiPlayer[] {
    return this.match.players.map((player, index) => {
      const holeScore = player.holeScores.find((score) => score.holeId === this.hole.id);
      const totalStrokes = player.holeScores.reduce((sum, score) => sum + score.strokes, 0);
      const parPlayed = player.holeScores.reduce((sum, score) => sum + this.parOf(score.holeId), 0);
      const status: UiPlayerStatus = holeScore?.completed
        ? 'finished'
        : player.id === this.match.activePlayerId
          ? 'playing'
          : 'waiting';
      return {
        id: player.id,
        name: player.displayName,
        color: this.colorOf(player.id, index),
        strokes: holeScore?.strokes ?? 0,
        totalStrokes,
        parDelta: totalStrokes - parPlayed,
        status,
        isLocal: player.kind === 'human',
      };
    });
  }

  private statusLine(): string {
    if (this.paused) return 'PAUSED';
    if (this.match.phase === 'match-results') return 'MATCH COMPLETE';
    if (this.match.phase === 'hole-intro') return this.introClock < 0 ? 'HOLE COMPLETE' : 'GET READY';
    if (this.statusText) return this.statusText.toUpperCase();
    if (this.match.phase === 'simulating') return 'BALL IN MOTION';
    const name = this.nameOf(this.turnPlayerId).toUpperCase();
    return this.isHumanTurn() ? name + ' · READY' : name + ' · TURN';
  }

  private hintText(): string {
    const shot =
      this.aim.controlScheme === 'drag-power'
        ? 'LMB drag back to aim and load power, release to putt'
        : 'Hold LMB or SPACE to charge, release to putt';
    return 'Move mouse to orbit · ' + shot + ' · WASD pan · wheel zoom · R recentre · TAB scores · ESC pause';
  }

  private toast(text: string): void {
    this.toastElement.textContent = text;
    this.toastElement.hidden = false;
    this.toastClock = TOAST_SECONDS;
  }

  private ballPosition(): Vec3 {
    if (this.turnPlayerId && this.ball) return this.ball.position;
    return this.playerPositions.get(this.turnPlayerId ?? '') ?? this.hole.spawn;
  }

  private isHumanTurn(): boolean {
    const playerId = this.turnPlayerId;
    return playerId !== undefined && !this.botProfiles.has(playerId);
  }

  private scoreOf(playerId: string): PlayerHoleScore | undefined {
    return this.match.players
      .find((player) => player.id === playerId)
      ?.holeScores.find((score) => score.holeId === this.hole.id);
  }

  private parOf(holeId: string): number {
    return this.course.holes.find((hole) => hole.id === holeId)?.par ?? 0;
  }

  private nameOf(playerId: string | undefined): string {
    return this.match.players.find((player) => player.id === playerId)?.displayName ?? 'Player';
  }

  private colorOf(playerId: string, index: number): string {
    const player = this.match.players.find((entry) => entry.id === playerId);
    const style = player ? ballStyleById(player.ballStyleId) : undefined;
    if (player?.kind === 'human' && style && style.id !== DEFAULT_BALL_ID) return style.color;
    return PLAYER_COLORS[index % PLAYER_COLORS.length] ?? '#ffffff';
  }

  private disposeBall(): void {
    if (!this.ball) return;
    this.physics.world.removeRigidBody(this.ball.body);
    this.ball = undefined;
  }
}
